using System;
using NUnit.Framework;
using Spacewars.Simulation;
using Spacewars.Runtime;
namespace Spacewars.Tests.EditMode
{
    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(false)][TestCase(true)]
        public void BodyArrivalMemberOwnAndProviderNamesKeepMetadataAliasesAndExactRecipe(bool qualified)
        {
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var provider=LayeredNavigationProvider.CopyOwned((LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(3,new NavObstacle[0],1)),r);
            var c=new NavClearanceProfile("ground",1,"ground",1,.25);var meta=NavGraphMetadata.CopyOptionalUnowned(c,new NavGraphProfile(new string('a',64),"distance",1,1),new NavGraphCompileLimits(2000,2000,10000),r);var origin=qualified?provider.Surfaces[0].OwnedLocation(new NavPoint(-1,0)):new NavLocation(new NavPoint(-1,0),NavLocation.FlatSurface);
            var publicMember=new NavArrivalMember(3,1,1,1,origin,c,1,1,1,1,0,1,1,1,"HOLD");var first=NavArrivalMember.CopyOwned(publicMember,meta.Clearance,r);var second=NavArrivalMember.CopyOwned(publicMember,meta.Clearance,r);Assert.AreSame(first.Clearance,second.Clearance);Assert.AreEqual(publicMember.StableKey,first.StableKey);Assert.AreSame(qualified?provider.Surfaces[0].StorageRoot:first.StorageRoot,first.Origin.NameReference.Owner);Assert.AreEqual(qualified?NavNameRole.SurfaceId:NavNameRole.ArrivalMemberOriginSurface,first.Origin.NameReference.Role);
            var bundle=NavRetainedArray<NavOwnedStorage>.Copy(new[]{first.StorageRoot,second.StorageRoot,(NavOwnedStorage)meta,provider.StorageRoot},birth.TryReserve);first.StorageRoot.ReleaseOwner();second.StorageRoot.ReleaseOwner();meta.Release();provider.StorageRoot.ReleaseOwner();birth.Attach(bundle);birth.Commit(bundle,_=>{});var bytes=CaptureGraph(hot,bundle);long charge=hot.PhysicalBytes;Assert.AreEqual(Unique(bundle),charge);
            byte[] Recipe(NavigationRetentionBudget budget,NavArrivalMember member,NavGraphMetadata metadata,ILayeredNavigationProvider p,out long physical){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Admission,1,200,out var scope));var originalName=member.Origin.NameReference;var sub=new NavRouteSubscription(member.WorldGeneration,member.GroupId,member.RootOrderRevision,member.CommandSequence,member.IssuedTick,member.ActivationRevision,member.EntityId,member.Incarnation,member.MemberOrderRevision,member.MobilityRevision,member.RequestSequence,member.Origin,new NavLocation(new NavPoint(1,0),NavLocation.FlatSurface),member.HoldBinding);var recipe=NavScheduledRequest.CreateOwned(p,member.Clearance,metadata.Profile,metadata.Limits,null,sub,4096,scope.OwnedReservation(),true);Assert.AreSame(member.Clearance,recipe.Clearance);Assert.AreEqual(NavNameRole.SurfaceId,recipe.Subscription.Origin.NameReference.Role);Assert.AreSame(originalName.Owner,member.Origin.NameReference.Owner);Assert.AreEqual(originalName.Role,member.Origin.NameReference.Role);Assert.AreEqual(originalName.Index,member.Origin.NameReference.Index);scope.Attach(recipe.StorageRoot);scope.Commit(recipe.StorageRoot,_=>{});var output=CaptureGraph(budget,recipe.StorageRoot);physical=Unique(recipe.StorageRoot);recipe.StorageRoot.ReleaseOwner();return output;}
            var expected=Recipe(hot,first,meta,provider,out long expectedCharge);CollectionAssert.AreEqual(bytes,CaptureGraph(hot,bundle));bundle.Release();bundle=null;first=null;second=null;meta=null;provider=null;publicMember=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var a=(NavArrivalMember)((NavDeclarationStorage)restored[0]).Facade;var b=(NavArrivalMember)((NavDeclarationStorage)restored[1]).Facade;var m=(NavGraphMetadata)restored[2];var p=(ILayeredNavigationProvider)((NavDeclarationStorage)restored[3]).Facade;Assert.AreSame(a.Clearance,b.Clearance);Assert.AreSame(m,a.Clearance.MetadataOwner);Assert.AreEqual(qualified?NavNameRole.SurfaceId:NavNameRole.ArrivalMemberOriginSurface,a.Origin.NameReference.Role);Assert.AreSame(qualified?p.Surfaces[0].StorageRoot:restored[0],a.Origin.NameReference.Owner);Assert.AreEqual(charge,cold.PhysicalBytes);Assert.AreEqual(Unique(restored),cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));CollectionAssert.AreEqual(expected,Recipe(cold,a,m,p,out long actualCharge));Assert.AreEqual(expectedCharge,actualCharge);
            NavArrivalMember Born(INavStorageReservation reservation)=>NavArrivalMember.CopyOwned(a,a.Clearance,reservation);
            Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,200,out var countedBirth));var counter=new Refusal(countedBirth,int.MaxValue);var born=Born(counter);countedBirth.Attach(born.StorageRoot);int sourceCalls=counter.Calls;countedBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            for(int nth=1;nth<=sourceCalls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,200+nth,out var rejectedBirth));var refusal=new Refusal(rejectedBirth,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejectedBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var foreignBirth));Assert.Throws<ArgumentException>(()=>Born(foreignBirth.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);foreignBirth.Discard();
            restored.Release();restored=null;a=null;b=null;m=null;p=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var count));var all=new Refusal(count,int.MaxValue);var trial=Decode(bytes,all);count.Attach(trial);int allocations=all.Calls;count.Discard();Assert.Zero(counted.PhysicalBytes);Assert.Zero(counted.HeldBytes);
            for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejected));var refusal=new Refusal(rejected,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejected.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
        }
    }
}
